<script setup lang="ts">import {Head,Link,router} from '@inertiajs/vue3';defineProps<{logs:any}>();</script><template><Head title="Log Notifikasi"/><main class="min-h-screen bg-slate-100 p-5"><section class="mx-auto max-w-7xl"><Link href="/admin/dashboard" class="text-emerald-700">← Dashboard</Link><h1 class="text-3xl font-bold text-emerald-950">Log notifikasi</h1><div class="mt-6 overflow-x-auto rounded-2xl bg-white"><table class="w-full text-left text-sm"><thead class="bg-emerald-950 text-white"><tr><th class="p-4">Pendaftar</th><th class="p-4">Channel/Event</th><th class="p-4">Penerima</th><th class="p-4">Status</th><th class="p-4">Error</th><th></th></tr></thead><tbody><tr v-for="l in logs.data" :key="l.id" class="border-b"><td class="p-4">{{l.applicant?.registration_number}}</td><td class="p-4">{{l.channel}} / {{l.event_type}}</td><td class="p-4">{{l.recipient_masked}}</td><td class="p-4">{{l.status}} ({{l.attempts}})</td><td class="max-w-xs p-4 text-red-700">{{l.last_error}}</td><td><button v-if="['failed','skipped'].includes(l.status)" @click="router.post(`/admin/notification-logs/${l.id}/retry`)" class="rounded-lg border px-3 py-1">Retry</button></td></tr></tbody></table></div></section></main></template>
